@dataclass
class LogEntry:
    timestamp: str
    level: str
    message: str
    color: str

def parse_log(log_text):
    entries = []
    for line in log_text.splitlines():
        parts = line.split('|')
        if len(parts) != 4:
            continue
        timestamp, level, message, color = parts
        entries.append(LogEntry(timestamp, level, message, color))
    return entries

